import {clone,uid,mul,translate,I} from './core.js';
export function graphIds(os,ids,{includeOwners=true}={}){const byId=new Map(os.map(o=>[o.id,o])),children=new Map();for(const o of os)for(const owner of new Set([o.source,o.panelOf,o.ownerId,o.attachment?.source,o.clip].filter(Boolean))){if(!children.has(owner))children.set(owner,[]);children.get(owner).push(o.id);}const set=new Set(),queue=[...ids];for(let i=0;i<queue.length;i++){const id=queue[i],o=byId.get(id);if(!o||set.has(id))continue;set.add(id);if(includeOwners)queue.push(...[o.source,o.panelOf,o.ownerId,o.clip,...(o.panelEdgeSelection?.required||[]).map(r=>r.source),...(o.panelEdgeSelection?.perimeter||[]).map(r=>r.source),...o.panelEdgeSelection?.scopeIds||[]].filter(Boolean));queue.push(...children.get(id)||[]);}return os.filter(o=>set.has(o.id)).map(o=>o.id);}
export function cloneGraph(os,ids,dx=12,dy=12){const selected=new Set(graphIds(os,ids)),originals=os.filter(o=>selected.has(o.id)),map=new Map(originals.map(o=>[o.id,uid()])),groups=new Map(),operations=new Map();const edgeMaps=new Map(originals.filter(o=>o.nodes).map(o=>[o.id,new Map()]));const edge=(owner,id)=>{if(!id)return id;const m=edgeMaps.get(owner);if(!m)return id;if(!m.has(id))m.set(id,uid());return m.get(id);};const remap=id=>map.get(id)||id;const copies=originals.map(o=>{const n=clone(o);n.id=remap(o.id);n.symmetryExcluded=true;n.mirrorPolicy='none';n.name+=' — copia';for(const k of ['mirrorPeer','instanceOf','symmetry','structureKey','mirrorMaster','mirrorDetached','mirrorAxisRef','mirrorScope','creationCommand'])delete n[k];for(const k of ['source','clip','panelOf','ownerId'])if(n[k])n[k]=remap(n[k]);if(n.attachment){if(map.has(n.attachment.source))n.attachment.source=remap(n.attachment.source);else delete n.attachment;}if(n.nodes)for(const path of [n,...n.subpaths||[]])for(const node of path.nodes){node.nid=uid();if(node.edgeId)node.edgeId=edge(o.id,node.edgeId);if(node.edgeParents)node.edgeParents=node.edgeParents.map(id=>edge(o.id,id));}if(n.semanticEdges)for(const [key,ids]of Object.entries(n.semanticEdges))n.semanticEdges[key]=ids.map(id=>edge(o.id,id));if(n.edgeIds)n.edgeIds=n.edgeIds.map(id=>edge(o.source||o.id,id));if(n.boundaryAnchors)n.boundaryAnchors=n.boundaryAnchors.map(a=>({...a,boundaryPieceId:remap(a.boundaryPieceId),boundarySegmentId:edge(a.boundaryPieceId,a.boundarySegmentId)}));if(n.panelEdgeSelection)for(const key of ['required','perimeter'])n.panelEdgeSelection[key]=n.panelEdgeSelection[key].map(r=>({...r,source:remap(r.source),edgeId:edge(r.source,r.edgeId)}));if(n.panelEdgeSelection?.scopeIds)n.panelEdgeSelection.scopeIds=n.panelEdgeSelection.scopeIds.map(remap);if(n.panelCuts)n.panelCuts=n.panelCuts.map(remap);if(n.regionIds)n.regionIds=n.regionIds.map(remap);if(n.group){if(!groups.has(n.group))groups.set(n.group,uid());n.group=groups.get(n.group);}for(const item of [n,...n.modifiers||[]]){if(item!==n){item.id=uid();if(item.edgeIds)item.edgeIds=item.edgeIds.map(id=>edge(o.id,id));}if(item.operationId){if(!operations.has(item.operationId))operations.set(item.operationId,uid());item.operationId=operations.get(item.operationId);}}if(!n.source&&!n.panelOf){n.matrix=mul(translate(dx,dy),n.matrix);if(n.collapseBackup)n.collapseBackup=mul(translate(dx,dy),n.collapseBackup);}return n;});for(let i=0;i<originals.length;i++){const o=originals[i],n=copies[i];if(o.instanceOf&&map.has(o.instanceOf)){n.instanceOf=map.get(o.instanceOf);n.mirrorPeer=n.instanceOf;n.mirrorPolicy='linked';delete n.symmetryExcluded;const m=copies.find(c=>c.id===n.instanceOf);m.mirrorPeer=n.id;m.mirrorPolicy='linked';delete m.symmetryExcluded;}}return {originals,copies,map};}
export function linkMirrorGraph(os,originals,copies,axis){const map=new Map(originals.map((o,i)=>[o.id,copies[i].id]));for(let i=0;i<copies.length;i++){const a=originals[i],b=copies[i];a.mirrorPeer=b.id;b.mirrorPeer=a.id;b.instanceOf=a.id;b.mirrorAxis=axis;a.mirrorPolicy=b.mirrorPolicy='linked';a.mirrorAxisRef=b.mirrorAxisRef='document-center';b.matrix=a.source?I():mul([-1,0,0,1,2*axis,0],a.matrix);if(a.panelOf)b.panelOf=map.get(a.panelOf)||a.panelOf;if(a.panelAnchor)b.panelAnchor=clone(a.panelAnchor);}}
